window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["synthetic-data"]={"title":"合成数据：生成候选容易，增加有效信息很难","subtitle":"从教师示范、程序真值、自训练和增强，到验证器选择偏差、覆盖配比、反馈回路与模型坍缩。","thesis":"合成数据的价值不来自“无限生成”，而来自针对真实缺口产生候选，再用独立证据筛选、去重、配比和追踪。最终保留分布由<b>生成器 × 验证器 × 采样权重</b>共同决定；验证器盲点和真实数据替换会放大错误、缩窄尾部。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"生成 100k","rule":"资格、金额和证据规则","steps":"规则通过 60k","interpretation":"漏斗的目标不是最大保留"}}],"formulas":[{"id":"synthetic-data-retained-distribution","section":3,"formulaIndex":1,"symbols":[{"name":"q","meaning":"生成或最终保留样本的相对概率分布","evidence":"最终分布 q保留"},{"name":"x","meaning":"合成得到的任务输入","evidence":"x 是合成输入"},{"name":"y","meaning":"与输入配套的标签、回答或轨迹","evidence":"y 是标签、回答或轨迹"},{"name":"a","meaning":"验证器接受某个候选样本的概率","evidence":"a(x,y) 是验证器接受它的概率"},{"name":"w","meaning":"控制主题、难度、语言或风险配额的保留权重","evidence":"w(x,y) 是为主题、难度、语言或风险设置的保留权重"}]},{"id":"synthetic-data-generational-mixture","section":7,"formulaIndex":1,"symbols":[{"name":"D","meaning":"某一代使用的训练数据分布","evidence":"Dₜ 是第 t 代模型看到的训练分布"},{"name":"t","meaning":"合成数据回流迭代的代数编号","evidence":"第 t 代生成数据分布"},{"name":"α","meaning":"当前训练混合中合成数据所占比例","evidence":"α 是合成数据所占比例"},{"name":"真实","meaning":"保留下来的原始真实数据分布","evidence":"D真实 是保留的原始真实数据分布"},{"name":"合成","meaning":"当前一代生成器产生的数据分布","evidence":"D合成,t 是第 t 代生成数据分布"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"合成数据是由模型、程序或模拟器产生，而非直接从目标世界观察的训练样本。","evidence":"合成数据 是由模型、程序或模拟器产生"},"problem":{"answer":"它针对真实数据缺口补充边界组合、改写、标签、结果或环境轨迹。","evidence":"先从真实失败切片定义缺什么"},"inputOutput":{"answer":"输入是待补失败切片和生成规则，输出是样本、标签、轨迹或执行结果。","evidence":"输出可以是输入、标签、推理轨迹"},"mechanism":{"answer":"生成器提出候选，独立证据筛选真正覆盖缺口且正确的样本。","evidence":"通过独立验证"},"interpretation":{"answer":"在合成集上变准只表示适应该集，必须看真实隔离集是否改善。","evidence":"最终要看真实隔离测试"},"boundary":{"answer":"生成数量不等于独立信息，开放世界事实不能由教师凭记忆创造。","evidence":"数量不代表独立性、新颖性或正确性"}},{"section":2,"definition":{"answer":"教师、程序、自训练和数据增强分别依赖不同的真值来源与保持假设。","evidence":"四种来源拥有不同真值结构"},"problem":{"answer":"它防止用同一信任规则处理教师偏差、模拟差距、自我确认和标签漂移。","evidence":"不能共用一套信任假设"},"inputOutput":{"answer":"输入是缺口、生成器和真值来源，输出是带来源类型与验证要求的数据管线。","evidence":"输出是带来源类型和验证要求的数据管线"},"mechanism":{"answer":"程序提供骨架，教师增加语言变化，再由规则或人工进行独立复核。","evidence":"程序构造可验证骨架"},"interpretation":{"answer":"来源标签表示信任结构不同，不应把所有合成样本视为同等可靠。","evidence":"不能混成“synthetic=true”一个标签"},"boundary":{"answer":"每类都有限制：程序有现实差距，教师有偏差，自训练会确认错误，增强会改标签。","evidence":"变换偷偷改标签"}},{"section":3,"definition":{"answer":"保留分布由生成频率、验证接受概率和覆盖配比权重共同相乘决定。","evidence":"三项相乘后还要对所有保留候选归一化"},"problem":{"answer":"它解释验证通过率很高时，保留集为何仍可能集中于简单重复样本。","evidence":"保留集仍可能充满简单重复题"},"inputOutput":{"answer":"输入是候选分布、接受概率和配额，输出是归一化后的最终训练分布。","evidence":"才得到总和为 1 的最终分布"},"mechanism":{"answer":"生成器限定可见候选，验证器筛选，权重再调整通过者的主题与难度比例。","evidence":"生成器决定候选能到哪里"},"interpretation":{"answer":"高接受率可能只表示生成器迎合弱验证器，不能单独证明数据质量。","evidence":"高接受率可能只是生成器迎合了弱验证器"},"boundary":{"answer":"验证器既删除错误也选择可存活的风格和解法，因此自身必须独立评测。","evidence":"验证器也是选择器"}},{"section":4,"definition":{"answer":"漏斗例把十万退款候选依次做规则验证、语义去重和覆盖配额筛选。","evidence":"10 万候选最后为何只保留 1.2 万"},"problem":{"answer":"它展示最大化候选或保留数量为何不是构造高价值训练集的目标。","evidence":"每一步损失与收益是什么"},"inputOutput":{"answer":"输入是十万候选，输出是一万二千条经验证、去重并按目标切片配额的数据。","evidence":"配额保留 12k"},"mechanism":{"answer":"规则去错、语义去重去近邻、配额再纠正语言难度与风险覆盖。","evidence":"最后按语言、难度和风险配额纠正剩余分布"},"interpretation":{"answer":"最终百分之十二接受率说明多数候选错误、重复或属于过量切片。","evidence":"总体接受率 12%"},"boundary":{"answer":"合成比例不能因候选便宜任意升高，真实锚点保留尾部和世界约束。","evidence":"真实锚点用于保留语言尾部和外部世界约束"}},{"section":5,"definition":{"answer":"可执行验证只证明测试、方程或解析规则明确写出的特定性质。","evidence":"执行器能证明特定性质"},"problem":{"answer":"它用于快速筛查代码、数学和结构化输出，却不能替代完整需求与安全真值。","evidence":"为什么训练样本仍可能有毒"},"inputOutput":{"answer":"输入是候选与测试或约束，输出是通过失败及可选的执行证据。","evidence":"程序在给定测试通过"},"mechanism":{"answer":"静态规则、执行、独立模型和人工多重验证，并用故意错误测试验证器。","evidence":"故意制造错误看能否拒绝"},"interpretation":{"answer":"通过表示满足已写断言，不表示覆盖未写边界、过程正确或没有漏洞。","evidence":"不能证明测试覆盖未写边界"},"boundary":{"answer":"生成器会寻找验证漏洞，同源教师和裁判也会共享盲点。","evidence":"两个模型都同意”不等于独立证据"}},{"section":6,"definition":{"answer":"覆盖评测把词面、语义、任务结构、解法和群体多样性分开衡量。","evidence":"词面、语义、结构、解法和群体多样性是不同维度"},"problem":{"answer":"它防止 embedding 距离或高温措辞变化冒充真实用户任务覆盖。","evidence":"真实用户输入仍可能覆盖不到"},"inputOutput":{"answer":"输入是合成候选、真实失败分类和切片，输出是多种覆盖与下游指标。","evidence":"输出是重复率、难度、覆盖、真假可分性和下游增益"},"mechanism":{"answer":"按真实失败建覆盖矩阵，每格设置目标量与真实锚点，再做隔离集消融。","evidence":"在每格设置目标量与真实锚点"},"interpretation":{"answer":"单一多样性指标不能证明现实相关、未知长尾或没有副作用。","evidence":"单项指标高不能互相替代"},"boundary":{"answer":"最终结论需比较真实基线、加合成、等量真实和打乱标签等对照。","evidence":"真实基线、加合成、等量真实、打乱标签等对照"}},{"section":7,"definition":{"answer":"模型坍缩是合成回流时尾部模式消失、错误和风格逐代放大的退化。","evidence":"稀有模式会逐代消失"},"problem":{"answer":"它判断模型学习模型输出是否必然退化，以及哪些混合方式加强反馈回路。","evidence":"是否必然一代比一代差"},"inputOutput":{"answer":"输入是真实与当代合成分布及比例，输出是下一代训练分布和覆盖变化。","evidence":"Dₜ 是第 t 代模型看到的训练分布"},"mechanism":{"answer":"替换真实数据且欠采样尾部会强化退化，保留真实锚点和配额可减弱。","evidence":"持续累积原始真实数据、限制合成比例"},"interpretation":{"answer":"平均准确率稳定而少数语言下降，仍表示尾部可能已经发生坍缩。","evidence":"少数语言与罕见场景可能已坍缩"},"boundary":{"answer":"合成并非必然崩溃，实际路径还取决于跨代累积、验证误差和覆盖控制。","evidence":"不能简化成“合成必崩”或“筛选就安全”"}},{"section":8,"definition":{"answer":"合成数据治理记录来源谱系、许可、敏感性、污染和可撤回路径。","evidence":"带稳定 ID、来源谱系、许可和撤回路径的样本"},"problem":{"answer":"它反驳自己生成的文本天然没有版权、隐私或测试污染问题。","evidence":"是否天然没有版权、隐私或测试污染问题"},"inputOutput":{"answer":"输入是种子、生成器、模板与验证器，输出是可追踪和可撤回的数据制品。","evidence":"治理输入是种子数据、生成器、模板、验证器和混合计划"},"mechanism":{"answer":"生成前查用途，生成后扫记忆、PII 和评测近邻，再去重、限额与隔离。","evidence":"生成后扫描记忆式片段"},"interpretation":{"answer":"扫描通过只说明当前规则未发现问题，不构成法律或权利结论。","evidence":"不是版权、隐私或授权结论"},"boundary":{"answer":"具体法律与合同义务随地区和用途变化，模型生成本身不决定权利。","evidence":"具体法律与合同判断需按地区和用途处理"}},{"section":9,"definition":{"answer":"合成数据决策比较其在真实缺口上的边际收益与收集真实数据的替代成本。","evidence":"何时值得用，何时应优先收集真实数据"},"problem":{"answer":"它识别规则明确可验证的适用任务，以及开放偏好和罕见伤害等高风险任务。","evidence":"最适合补哪类缺口"},"inputOutput":{"answer":"输入是缺口、验证能力、真实数据成本和风险，输出是合成、真实或组合方案。","evidence":"比较“加合成”与“等预算真实/人工/工具改进”"},"mechanism":{"answer":"先小规模对照并按切片看边际增益，真实指标不升就停止扩量。","evidence":"真实指标不升，应停止扩量"},"interpretation":{"answer":"只更像教师而真实指标不升，表示迁移教师风格而非解决真实缺口。","evidence":"合成只让模型更像教师"},"boundary":{"answer":"开放世界事实、文化偏好、罕见伤害与真实意图更需要真实观察和专家参与。","evidence":"应投资真实观察、专家标注与参与式评估"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分四类生成机制；推导接受率与保留分布；设计生成—验证—混合闭环；识别坍缩、污染与同源偏差。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>合成的是样本，不是自动产生新知识<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">大模型写出一百万条问答，为什么有效信息可能只相当于几千条？</p><p><b>合成数据</b>是由模型、程序或模拟器产生，而非直接从目标世界观察并人工记录的训练样本。生成器会复述训练中常见模式，采样之间高度相关；数量不代表独立性、新颖性或正确性。输入是待补的真实失败切片与生成规则，输出可以是输入、标签、推理轨迹、偏好对、代码结果或模拟轨迹。</p><p>样本只有覆盖真实缺口并通过独立验证，才可能增加有效信息。退款助手可合成政策边界组合、口语改写和工具错误轨迹，但真实政策事实必须来自权威规则，不能让教师凭记忆创造。模型在合成集上更准也只说明适应了该集，最终要看真实隔离测试。</p><div class=\"dd-note\"><b>正确起点：</b>先从真实失败切片定义缺什么，再选择生成机制；不要先生成海量数据再寻找用途。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>四种来源拥有不同真值结构<span class=\"dd-badge eng\">分类</span></h2><p class=\"dd-lead\">教师模型、程序、伪标签和数据增强为什么不能共用一套信任假设？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>来源</th><th>生成什么</th><th>真值来自</th><th>主要失败</th></tr></thead><tbody><tr><td>教师蒸馏</td><td>示范、解释、偏好</td><td>教师能力/外部核验</td><td>传递偏差与风格</td></tr><tr><td>程序/模拟器</td><td>题目、标签、轨迹</td><td>规则、执行、求解器</td><td>模拟与现实差距</td></tr><tr><td>自训练</td><td>未标注输入伪标签</td><td>模型置信/一致性</td><td>确认自身错误</td></tr><tr><td>数据增强</td><td>改写、扰动、变换</td><td>标签应保持不变</td><td>变换偷偷改标签</td></tr></tbody></table></div><p>输入是缺口类型、可用生成器和可获得的真值来源，输出是带来源类型和验证要求的数据管线。程序骨架适合规则明确任务，教师适合语言多样性，自训练依赖模型已有可靠区域，增强则要求变换不改变标签。</p><p>最强组合常是程序构造可验证骨架，再让教师增加语言多样性，最后以规则和人工抽样复核。<b>数据谱系（provenance）</b>就是记录样本由哪个输入、生成器、版本和验证步骤产生；不同来源必须保留谱系，不能混成“synthetic=true”一个标签，否则出现错误时无法撤回或区分信任强度。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>生成器、验证器和配比共同定义训练分布<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">为什么验证通过率很高，保留集仍可能充满简单重复题？</p><div class=\"dd-formula\" data-formula-id=\"synthetic-data-retained-distribution\"><math display=\"block\" aria-label=\"最终保留样本 x y 的相对密度，正比于生成器产生该样本的密度，乘验证器接受概率，再乘覆盖权重\"><mrow><msub><mi>q</mi><mtext>保留</mtext></msub><mo>(</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo>)</mo><mo>∝</mo><msub><mi>q</mi><mtext>生成</mtext></msub><mo>(</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo>)</mo><mo>·</mo><mi>a</mi><mo>(</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo>)</mo><mo>·</mo><mi>w</mi><mo>(</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo>)</mo></mrow></math></div><p class=\"dd-formula-note\"><code>x</code> 是合成输入，<code>y</code> 是标签、回答或轨迹；<code>q生成(x,y)</code> 表示生成器多常产生该候选，<code>a(x,y)</code> 是验证器接受它的概率，<code>w(x,y)</code> 是为主题、难度、语言或风险设置的保留权重。符号 <code>∝</code> 表示“成比例”：三项相乘后还要对所有保留候选归一化，才得到总和为 1 的最终分布 <code>q保留</code>。</p><p>生成器决定候选能到哪里，验证器决定谁能通过，配比权重决定通过者各保留多少。若验证器只会检查最终金额，错误理由偶然算对也会被接受；若简单题通过率更高，筛选会把分布进一步推向简单。</p><p>因此同时报告候选数、接受率、去重后数量、难度与切片覆盖、验证器误差和与真实目标分布的距离。高接受率可能只是生成器迎合了弱验证器。</p><div class=\"dd-note warn\"><b>验证器也是选择器。</b>　它不仅去掉坏样本，还定义哪些风格和解法能存活，必须独立评测。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：10 万候选最后为何只保留 1.2 万<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">退款边界数据经过规则、去重和覆盖采样，每一步损失与收益是什么？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 710 255\" role=\"img\" aria-label=\"十万条合成退款样本经过规则验证、语义去重、覆盖配额和人工抽样形成训练混合\"><defs><marker id=\"sd1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"16\" y=\"88\" width=\"118\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"75\" y=\"114\" text-anchor=\"middle\" class=\"svg-t\">生成 100k</text><text x=\"75\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">教师+模板候选</text><path d=\"M134,122 L168,122\" stroke=\"#6b7484\" marker-end=\"url(#sd1)\"/><rect x=\"170\" y=\"88\" width=\"118\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"229\" y=\"114\" text-anchor=\"middle\" class=\"svg-t\">规则通过 60k</text><text x=\"229\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">资格/金额/证据</text><path d=\"M288,122 L322,122\" stroke=\"#6b7484\" marker-end=\"url(#sd1)\"/><rect x=\"324\" y=\"88\" width=\"118\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"383\" y=\"114\" text-anchor=\"middle\" class=\"svg-t\">去重后 24k</text><text x=\"383\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">大量措辞近邻</text><path d=\"M442,122 L476,122\" stroke=\"#6b7484\" marker-end=\"url(#sd1)\"/><rect x=\"478\" y=\"88\" width=\"118\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"537\" y=\"114\" text-anchor=\"middle\" class=\"svg-t\">配额保留 12k</text><text x=\"537\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">语言/难度/风险</text><path d=\"M596,122 L630,122\" stroke=\"#6b7484\" marker-end=\"url(#sd1)\"/><rect x=\"632\" y=\"88\" width=\"62\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"663\" y=\"114\" text-anchor=\"middle\" class=\"svg-t\">混合</text><text x=\"663\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">≤20%</text><path d=\"M537,157 C530,217 227,221 229,158\" fill=\"none\" stroke=\"#c77b72\" stroke-dasharray=\"5 4\" marker-end=\"url(#sd1)\"/><text x=\"383\" y=\"214\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">训练后真实留出集发现新错误 → 回到缺口定义，不直接学习自身输出</text></svg><figcaption>图 1　漏斗的目标不是最大保留，而是留下可验证、非重复且覆盖目标切片的数据。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>阶段</th><th>数量</th><th>相对上一步</th><th>需抽查的问题</th></tr></thead><tbody><tr><td>生成</td><td>100k</td><td>100%</td><td>是否真的覆盖缺口</td></tr><tr><td>规则验证</td><td>60k</td><td>60%</td><td>验证器漏错/误拒</td></tr><tr><td>语义去重</td><td>24k</td><td>40%</td><td>是否误删稀有表达</td></tr><tr><td>覆盖采样</td><td>12k</td><td>50%</td><td>真实目标权重与长尾</td></tr></tbody></table></div><p>管线先按资格、金额和证据规则去掉明显错误，再用语义近邻删除重复措辞，最后按语言、难度和风险配额纠正剩余分布。每一步都要抽查误拒和误删，不能把数量减少本身当作质量提升。</p><p>总体接受率 12%。若训练混合共 60k 样本，12k 合成占 20%；不能因为候选免费就把比例提高到 90%，真实锚点用于保留语言尾部和外部世界约束。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>可执行验证强，但只强在写出的断言<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">代码通过单测、数学答案代入正确，为什么训练样本仍可能有毒？</p><p>执行器能证明特定性质：程序在给定测试通过、方程结果满足、JSON 可解析。它不能证明测试覆盖未写边界、推理过程无错误、需求本身正确或代码无安全漏洞。生成器还会寻找验证器漏洞，形成 reward hacking。</p><p>使用多重验证：静态规则 + 执行 + 独立模型/人工；对验证器做 mutation test，故意制造错误看能否拒绝；维护隐藏测试和定期更新，避免生成器过拟合公开断言。高风险数据需要来源证据而非多数模型投票。</p><div class=\"dd-note warn\"><b>同源偏差：</b>同系列教师和裁判可能共享盲点；“两个模型都同意”不等于独立证据。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>多样性、难度与真实性必须分别测<span class=\"dd-badge eng\">覆盖</span></h2><p class=\"dd-lead\">embedding 距离看起来很多样，为什么真实用户输入仍可能覆盖不到？</p><p><b>embedding 距离</b>是把文本变成向量后测量两段文本在表示空间相隔多远，常用于找语义近邻；距离大只说明当前表示认为它们不同，不保证任务结构或用户群体真的新颖。词面、语义、结构、解法和群体多样性是不同维度；随机高温可增加措辞却不增加任务结构。</p><p>输入是合成候选、真实失败分类和目标切片，输出是重复率、难度、覆盖、真假可分性和下游增益等互补指标。按真实失败分类建立覆盖矩阵：语言、政策边界、缺失字段、冲突证据、攻击和工具故障；在每格设置目标量与真实锚点。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>指标</th><th>回答</th><th>不能证明</th></tr></thead><tbody><tr><td>n-gram/语义重复率</td><td>是否近邻太多</td><td>任务结构新颖</td></tr><tr><td>难度分层</td><td>验证/模型成功分布</td><td>现实相关性</td></tr><tr><td>切片覆盖</td><td>预定义组合是否出现</td><td>未知长尾已覆盖</td></tr><tr><td>真实/合成分类器</td><td>分布可分程度</td><td>哪一边更正确</td></tr><tr><td>下游增益</td><td>训练后任务变化</td><td>无副作用与因果唯一</td></tr></tbody></table></div><p>单项指标高不能互相替代：语义多样不证明现实相关，切片齐全不证明未知长尾覆盖。最终证据来自真实隔离测试和消融：真实基线、加合成、等量真实、打乱标签等对照。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>模型坍缩取决于替换、累积和筛选方式<span class=\"dd-badge math\">反馈回路</span></h2><p class=\"dd-lead\">模型学习模型输出是否必然一代比一代差？</p><p>若每代用生成样本替换真实数据，生成器欠采样尾部，稀有模式会逐代消失；系统错误和风格被放大。若持续累积原始真实数据、限制合成比例、引入独立验证和多样性配额，退化路径会显著不同，因此不能简化成“合成必崩”或“筛选就安全”。</p><div class=\"dd-formula\" data-formula-id=\"synthetic-data-generational-mixture\"><math display=\"block\" aria-label=\"第 t 代训练分布等于一减 alpha 乘真实数据分布，加 alpha 乘第 t 代合成数据分布\"><mrow><msub><mi>D</mi><mi>t</mi></msub><mo>=</mo><mo>(</mo><mn>1</mn><mo>−</mo><mi>α</mi><mo>)</mo><msub><mi>D</mi><mtext>真实</mtext></msub><mo>+</mo><mi>α</mi><msub><mi>D</mi><mrow><mtext>合成</mtext><mo>,</mo><mi>t</mi></mrow></msub></mrow></math></div><p class=\"dd-formula-note\"><code>Dₜ</code> 是第 t 代模型看到的训练分布，<code>D真实</code> 是保留的原始真实数据分布，<code>D合成,t</code> 是第 t 代生成数据分布，<code>α</code> 是合成数据所占比例。这个式子只描述混合权重；真实数据是否跨代累积、生成器漏掉哪些尾部以及验证器误差，都会改变实际反馈强度。</p><p>监控尾部覆盖、熵、重复、真实与合成可分性、跨代错误相关和真实留出表现。平均准确率稳定时，少数语言与罕见场景可能已坍缩；只有在真实隔离切片上持续验证，才能区分整体稳定与尾部消失。</p><div class=\"dd-note warn\"><b>来源标签不可丢。</b>　互联网中的模型生成内容若未标识，会使团队误把合成回流当新真实数据。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>谱系、污染和授权仍适用于合成数据<span class=\"dd-badge eng\">治理</span></h2><p class=\"dd-lead\">自己生成的文本是否天然没有版权、隐私或测试污染问题？</p><p>教师可能复述训练内容或个人信息，提示中可能包含受限文档，生成的改写可能与评测题近邻。PII 是可用于识别个人的信息，例如姓名与联系方式；评测污染是训练数据包含测试题或近似答案，使成绩虚高。</p><p>治理输入是种子数据、生成器、模板、验证器和混合计划，输出是带稳定 ID、来源谱系、许可和撤回路径的样本。记录生成器快照、提示模板、采样、种子、输入来源、验证器版本、拒绝原因和最终混合。</p><ol class=\"dd-steps\"><li>生成前检查种子数据用途和敏感性。</li><li>生成后扫描记忆式片段、PII、恶意内容与评测近邻。</li><li>语义去重并保留簇与代表样本。</li><li>按来源/难度/群体设上限，防单一教师支配。</li><li>隔离真实留出集，禁止其题目和派生答案进入提示。</li><li>发现问题可沿谱系撤回数据并定位训练运行。</li></ol><p>扫描通过只说明当前规则未发现问题，不是版权、隐私或授权结论。“模型生成”也不是权利结论，具体法律与合同判断需按地区和用途处理。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>何时值得用，何时应优先收集真实数据<span class=\"dd-badge intuition\">决策</span></h2><p class=\"dd-lead\">合成数据最适合补哪类缺口，又在哪些任务上最容易自欺？</p><p>适合：规则真值明确、模拟器可靠、可执行验证、隐私安全的边界组合、真实样本极少但结构已知。谨慎：开放世界事实、文化偏好、罕见伤害、真实用户意图和验证器与教师同源的任务。后者应投资真实观察、专家标注与参与式评估。</p><p>在小规模试验中比较“加合成”与“等预算真实/人工/工具改进”，按切片看边际收益；若合成只让模型更像教师而真实指标不升，应停止扩量。生成成本便宜不代表筛选、治理和错误成本便宜。</p><div class=\"dd-note\"><b>停止条件：</b>新增批次去重后新颖性、真实留出增益或边际覆盖接近零时，不应继续为数量 KPI 生成。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">合成数据是一条受控实验管线，不是一台无限知识打印机。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>样本越多信息越多</td><td>相关重复和常见模式可能几乎不增加覆盖</td></tr><tr><td>验证通过就是真值</td><td>只证明验证器写出的性质且可能被利用</td></tr><tr><td>高温生成等于任务多样</td><td>可能只改措辞，不改结构和长尾</td></tr><tr><td>合成数据必然坍缩</td><td>风险取决于真实数据累积、比例、筛选和任务</td></tr><tr><td>自己生成无需治理</td><td>仍有来源、隐私、污染、授权和撤回问题</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>监督/自监督学习、蒸馏、数据分布与评测</td></tr><tr><td><b>本页核心</b></td><td>生成—验证—去重—配比、反馈回路与真实锚点</td></tr><tr><td>数据治理</td><td>训练数据治理、隐私、评测污染与数据投毒</td></tr><tr><td>方法延伸</td><td>后训练、可验证奖励、自训练和世界模型模拟</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>从真实失败定义可量化缺口</li><li>选择带合适真值结构的生成机制</li><li>用独立规则/执行/人工验证</li><li>语义去重并按难度/群体配额</li><li>限制混合比例并保留真实锚点</li><li>在真实隔离集消融并沿谱系迭代</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么十万候选示例最后只保留 1.2 万？</li><li>q_keep 由哪三部分共同决定？</li><li>执行验证为何不是完整真值？</li><li>合成回流何时易坍缩？</li><li>为何必须保留真实隔离集？</li><li>假设“合成数据：生成候选容易，增加有效信息很难”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“合成数据：生成候选容易，增加有效信息很难”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>规则验证、语义去重和覆盖配额依次删除错误、重复与过量切片。</li><li>生成分布 q_gen、验证接受概率 a 和覆盖/难度权重 w。</li><li>只证明写出的测试或约束，可能漏边界、过程错误和现实差距。</li><li>生成数据替换真实数据、尾部欠采样、错误同源且缺独立筛选时。</li><li>避免生成器/验证器自洽地高分，却偏离真实用户与世界。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2212.10560\" target=\"_blank\" rel=\"noopener\">Self-Instruct</a>：模型生成指令数据与筛选</li><li><a href=\"https://arxiv.org/abs/2305.17493\" target=\"_blank\" rel=\"noopener\">The Curse of Recursion</a>：生成数据反馈与模型坍缩</li><li><a href=\"https://arxiv.org/abs/2404.01413\" target=\"_blank\" rel=\"noopener\">Is Model Collapse Inevitable?</a>：累积真实与合成数据对坍缩的影响</li><li><a href=\"https://arxiv.org/abs/2306.11644\" target=\"_blank\" rel=\"noopener\">Textbooks Are All You Need</a>：受控高质量合成代码数据</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
